style.css:
@-moz-document url-prefix("https://aureus.wtf/dashboard/") {
/* Backgrounds */
    body, .main-content, .container, .card, .panel {
        background-color: #f0f8ff !important; /* soft light blue background */
        border: 1px solid #74b9ff !important; /* subtle blue border */
        box-shadow: 0 2px 6px rgba(116, 185, 255, 0.15) !important;
        border-radius: 8px !important;
        padding: 15px !important;
    }

    /* Buttons */
    button, .button, .btn {
        background-color: #0984e3 !important;
        border: 1px solid #0652dd !important;
        color: white !important;
        border-radius: 6px !important;
        padding: 8px 16px !important;
        font-weight: 700 !important;
        cursor: pointer !important;
        box-shadow: 0 3px 8px rgba(9, 132, 227, 0.35) !important;
        transition: background-color 0.25s ease !important;
        margin: 4px 0 !important;
    }
    button:hover, .button:hover, .btn:hover {
        background-color: #0652dd !important;
        box-shadow: 0 5px 15px rgba(6, 82, 221, 0.55) !important;
    }

    /* Inputs, selects, textareas */
    input, textarea, select {
        background-color: #dff6ff !important;
        border: 1px solid #74b9ff !important;
        border-radius: 6px !important;
        padding: 8px 10px !important;
        font-weight: 600 !important;
        margin-bottom: 12px !important;
        width: 100% !important;
        box-sizing: border-box !important;
        color: inherit !important; /* keep original text color */
    }

    /* Links (just color, no text overrides) */
    a {
        color: #0984e3 !important;
        text-decoration: underline !important;
    }
    a:hover {
        color: #0652dd !important;
    }

    /* Keep all text colors untouched except links */
    /* No universal color changes to avoid breaking text */

    /* Tables */
    table {
        width: 100% !important;
        border-collapse: collapse !important;
        margin-bottom: 20px !important;
    }
    th, td {
        border: 1px solid #74b9ff !important;
        padding: 10px !important;
        text-align: left !important;
        background-color: #e6f0ff !important;
    }
    th {
        background-color: #b2dffc !important;
    }

    /* Icons */
    svg, .icon, .icon-primary {
        fill: #0984e3 !important;
        color: #0984e3 !important;
    }
}
